//! Lombok awareness: code generated by Lombok annotations reads and writes fields, so rules
//! about unused fields/accessors must not fire on Lombok-annotated classes and fields.

use crate::ctx::Ctx;
use crate::kinds::{k, K};
use crate::syntax::{annotation_name, annotations, node_text};
use crate::syntax::{Field, NodeExt};
use tree_sitter::Node;

/// Class-level Lombok annotations (simple names).
const CLASS_ANNOTATIONS: &[&str] = &[
    "Data",
    "Value",
    "Getter",
    "Setter",
    "Builder",
    "SuperBuilder",
    "AllArgsConstructor",
    "NoArgsConstructor",
    "RequiredArgsConstructor",
    "ToString",
    "EqualsAndHashCode",
    "With",
    "Wither",
    "Accessors",
    "FieldDefaults",
    "FieldNameConstants",
    "Jacksonized",
    "UtilityClass",
    "Log",
    "Slf4j",
    "XSlf4j",
    "Log4j",
    "Log4j2",
    "CommonsLog",
    "JBossLog",
    "Flogger",
    "CustomLog",
];

/// Annotations that make Lombok generate accessors (or other readers) for a field.
const ACCESSOR_ANNOTATIONS: &[&str] = &["Getter", "Setter", "With", "Wither", "Delegate"];
/// Class annotations that generate accessors or otherwise read every field.
const CLASS_FIELD_READERS: &[&str] = &[
    "Data",
    "Value",
    "Getter",
    "Setter",
    "With",
    "ToString",
    "EqualsAndHashCode",
    "Builder",
    "SuperBuilder",
    "AllArgsConstructor",
];

impl<'t> Ctx<'t> {
    /// Whether the source mentions `lombok` at all (once per file): without it, no annotation
    /// can be qualified with `lombok.` and nothing is imported from Lombok, so the questions
    /// below are answered without looking at any annotation.
    fn mentions_lombok(&self) -> bool {
        *self.lombok.get_or_init(|| self.src.contains("lombok"))
    }

    /// Whether this file imports anything from Lombok.
    fn imports_lombok(&self) -> bool {
        self.imports
            .iter()
            .any(|i| i.path == "lombok" || i.path.starts_with("lombok."))
    }

    fn is_lombok_annotation(&self, ann: Node<'t>, set: &[&str]) -> bool {
        let full = ann
            .field(Field::Name)
            .map(|n| node_text(n, self.src))
            .unwrap_or("");
        if let Some(rest) = full.strip_prefix("lombok.") {
            let simple = rest.rsplit('.').next().unwrap_or(rest);
            return set.contains(&simple);
        }
        !full.contains('.')
            && set.contains(&annotation_name(ann, self.src))
            && self.imports_lombok()
    }

    /// Whether a class-like declaration carries a Lombok annotation (`@Data`, `@Getter`,
    /// `@Builder`, `@Slf4j`, …). Requires the annotation to be qualified with `lombok.` or the
    /// file to import from `lombok`.
    pub fn has_lombok(&self, class: Node<'t>) -> bool {
        let _g = self.section(crate::timing::Section::Resolver);
        self.mentions_lombok()
            && annotations(class).any(|a| self.is_lombok_annotation(a, CLASS_ANNOTATIONS))
    }

    /// Whether Lombok generates code that reads/writes this field: the `field_declaration`
    /// has `@Getter`/`@Setter`/`@With`/`@Delegate`, or its class has `@Data`, `@Value`,
    /// `@Getter`, `@Setter`, `@ToString`, `@EqualsAndHashCode`, `@Builder`, ….
    pub fn field_has_generated_accessors(&self, field_decl: Node<'t>) -> bool {
        let _g = self.section(crate::timing::Section::Resolver);
        if !self.mentions_lombok() {
            return false;
        }
        if annotations(field_decl).any(|a| self.is_lombok_annotation(a, ACCESSOR_ANNOTATIONS)) {
            return true;
        }
        let Some(class) = self.enclosing_class(field_decl) else {
            return false;
        };
        k(class).is_type_decl()
            && k(class) != K::InterfaceDecl
            && annotations(class).any(|a| self.is_lombok_annotation(a, CLASS_FIELD_READERS))
    }
}
